package ru.neverland.townybuilds;
import java.util.*;import java.io.*;
import org.bukkit.Material;import org.bukkit.inventory.ItemStack;
import ru.neverland.townybuilds.api.CargoShipment;
import ru.neverland.townybuilds.data.TownData;
import ru.neverland.townybuilds.storage.*;
public final class CampDeliverySmoke {
    static final class Item extends ItemStack {int amount;Item(int n){super();amount=n;}public Material getType(){return Material.BREAD;}public int getAmount(){return amount;}public void setAmount(int n){amount=n;}public int getMaxStackSize(){return 64;}public Item clone(){return new Item(amount);}public boolean isSimilar(ItemStack i){return i instanceof Item;}}
    static final class Access implements ShipmentTransactions.Access{ItemStack[] source=new ItemStack[9];boolean fail;public ItemStack[] read(String id){return StockMath.copy(source);}public void write(String id,ItemStack[] items){source=StockMath.copy(items);}public boolean busy(String id){return false;}public void commit()throws IOException{if(fail)throw new IOException("disk full");}}
    static final class Receiver implements CampDeliveries.Receiver{boolean credited,offline;int credits;public boolean received(UUID t,UUID i,UUID c,ItemStack[] cargo)throws Exception{if(offline)throw new IOException("provider absent");return credited;}public boolean receive(UUID t,UUID i,UUID c,ItemStack[] cargo){if(!credited){credited=true;credits++;}return true;}}
    static void check(boolean b,String m){if(!b)throw new AssertionError(m);}interface Work{void run()throws Exception;}static void fails(Work w)throws Exception{try{w.run();}catch(IOException expected){return;}throw new AssertionError();}
    public static void main(String[] args)throws Exception{UUID town=UUID.randomUUID(),camp=UUID.randomUUID(),id=UUID.randomUUID();var data=new TownData(town,54);data.putShipment(new CargoShipment(id,"army","warehouse","raid_camp:"+camp,new ItemStack[]{new Item(20)},"TRANSIT",1));var a=new Access();var r=new Receiver();a.fail=true;fails(()->CampDeliveries.unload(town,data,a,r,id,false));check(r.credits==1&&data.shipments().get(id).inTransit(),"destination committed but source ack failed");a.fail=false;check(CampDeliveries.unload(town,data,a,r,id,true),"recovery consults receipt before refund");check(r.credits==1&&StockMath.total(a.source)==0&&data.shipments().get(id).status().equals("DELIVERED"),"no duplicate resources from emergency return");
        UUID second=UUID.randomUUID();data.putShipment(new CargoShipment(second,"army","warehouse","raid_camp:"+camp,new ItemStack[]{new Item(10)},"TRANSIT",2));r.credited=false;r.offline=true;fails(()->CampDeliveries.unload(town,data,a,r,second,true));check(data.shipments().get(second).inTransit()&&StockMath.total(a.source)==0,"missing destination evidence holds escrow");r.offline=false;check(CampDeliveries.unload(town,data,a,r,second,true)&&StockMath.total(a.source)==10,"uncredited cargo returned once");check(CampDeliveries.unload(town,data,a,r,second,true)&&StockMath.total(a.source)==10,"repeat return safe");System.out.println("CampDeliverySmoke PASS: partial commit, destination outage, no refund after credit, replay and exact return");}
}
